import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { PDFDocumentProxy } from "pdfjs-dist";
import { pdfChapterRanges } from "@shared/pdfText";
import { pdfChapterContent, pdfHasText, pdfOutlineEntries } from "./pdfExtract";

/**
 * Runs the real pdf.js over the committed fixtures (generated by
 * src/bun/formats/fixtures/generate.ts). The app uses the modern build in a
 * Web Worker; under bun the legacy build parses on the main thread instead.
 */
async function open(name: string): Promise<PDFDocumentProxy> {
	const pdfjs = await import("pdfjs-dist/legacy/build/pdf.mjs");
	const data = new Uint8Array(
		readFileSync(join(import.meta.dir, "../../../../bun/formats/fixtures", name)),
	);
	return pdfjs.getDocument({ data, useWasm: false, verbosity: 0 }).promise as Promise<PDFDocumentProxy>;
}

describe("PDF extraction", () => {
	test("chapters come from the outline; text keeps reading order", async () => {
		const doc = await open("outline.pdf");
		expect(await pdfHasText(doc)).toBe(true);
		const outline = await pdfOutlineEntries(doc);
		expect(outline).toEqual([
			{ title: "Chapter One", pageIndex: 1 },
			{ title: "Chapter Two", pageIndex: 3 },
		]);
		const ranges = pdfChapterRanges(outline, doc.numPages);
		expect(ranges.map((r) => r.title)).toEqual(["Front matter", "Chapter One", "Chapter Two"]);

		const one = await pdfChapterContent(doc, ranges[1]!);
		expect(one.html).toBe(
			[
				"<p>Chapter One</p>",
				"<p>The first paragraph runs over two lines and ends with a hyphenated word that must be joined again.</p>",
				"<p>A second paragraph follows after a gap and its sentence is cut by the page break, then carries on at the top of the next page.</p>",
			].join("\n"),
		);
		expect(one.text.replace(/\s+/g, " ")).toContain("Chapter One The first paragraph");
	});

	test("without an outline, pages are grouped by ten", async () => {
		const doc = await open("plain.pdf");
		const ranges = pdfChapterRanges(await pdfOutlineEntries(doc), doc.numPages);
		expect(ranges.map((r) => r.title)).toEqual(["Pages 1–10", "Pages 11–12"]);
		const last = await pdfChapterContent(doc, ranges[1]!);
		expect(last.html).toBe("<p>This is the text of page 11.</p>\n<p>This is the text of page 12.</p>");
	});

	test("two columns are read one after the other, not line by line across", async () => {
		const doc = await open("columns.pdf");
		const { html } = await pdfChapterContent(doc, { id: "p0", title: "", start: 0, end: 1 });
		expect(html).toBe(
			"<p>Left one left two left three left four.</p>\n<p>Right one right two right three right four.</p>",
		);
	});

	test("a scanned PDF has no text", async () => {
		expect(await pdfHasText(await open("scanned.pdf"))).toBe(false);
	});
});
